<script setup lang="ts">
import {computed} from 'vue';
import PublicationRecovery from './PublicationRecovery.vue';
import {AlertCircle,ArrowRight,CheckCircle2,LoaderCircle} from 'lucide-vue-next';
type Item=Record<string,any>;
const props=defineProps<{approvals:Item[];projects:Item[];tenants:Item[];request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const emit=defineEmits<{project:[id:string];updated:[]}>();
const operations=computed(()=>props.approvals.filter(item=>(item.type==='manual'&&item.status!=='pending')||(item.type==='publish'&&['failed','completed'].includes(item.status)&&item.payload?.publication_attempt?.started_at)).slice(0,10));
function label(status:string){return ({approved:'Na fila',executing:'Em execução',completed:'Concluída',failed:'Requer atenção',expired:'Revisão expirada',rejected:'Recusada',cancelled:'Cancelada'} as Record<string,string>)[status]??status;}
function project(id:string){return props.projects.find(item=>item.id===id);}
function tenant(approval:Item){return props.tenants.find(item=>String(item.id)===String(approval.payload?.revision?.tenant_id))?.name??('Tenant #'+approval.payload?.revision?.tenant_id);}
</script>
<template><section v-if="operations.length" class="bi-operations" aria-label="Operações de BI"><h2>Operações de BI</h2><article v-for="operation in operations" :key="operation.id"><div class="operation-title"><LoaderCircle v-if="['approved','executing'].includes(operation.status)" :size="18" class="spin"/><AlertCircle v-else-if="operation.status==='failed'" :size="18"/><CheckCircle2 v-else :size="18"/><div><strong>{{operation.title}}</strong><p>{{operation.payload?.revision?.schedule_edit?.name||operation.payload?.action?.values?.name||operation.payload?.revision?.publication?.source?.name||operation.payload?.action?.name||operation.payload?.revision?.info?.data?.nome||operation.payload?.action?.resource}} · {{tenant(operation)}}</p></div><span class="operation-status" :class="[operation.status,{attention:operation.payload?.execution?.result?.management_warning}]">{{operation.status==='completed'&&operation.payload?.execution?.result?.management_warning?'Concluída com pendência':label(operation.status)}}</span></div><p v-if="operation.payload?.execution?.message" class="operation-message">{{operation.payload.execution.message}}</p><p v-if="operation.payload?.execution?.result?.management_warning" class="operation-message">{{operation.payload.execution.result.management_warning}}</p><PublicationRecovery :approval="operation" :request="request" @confirmed="emit('updated')"/><button v-if="project(operation.project_id)" class="text-button" @click="emit('project',operation.project_id)">Abrir projeto<ArrowRight :size="14"/></button></article></section></template>
<style scoped>.bi-operations{margin:28px 0}.bi-operations h2{font-size:15px;color:#2d405f;margin-bottom:15px}.bi-operations article{border:1px solid #e0e7f1;border-radius:9px;background:white;padding:17px;margin-bottom:10px}.operation-title{display:flex;align-items:flex-start;gap:10px;color:#496792}.operation-title strong{font-size:12px;color:#2b4165}.operation-title p,.operation-message{font-size:11px;line-height:1.7;color:#738198;margin-top:5px}.operation-status{margin-left:auto;font-size:10px;white-space:nowrap;color:#5e7190;background:#eef3fb;border-radius:5px;padding:4px 7px}.operation-status.completed{background:#e9f6ed;color:#277950}.operation-status.failed,.operation-status.attention{background:#fff3e8;color:#9e592f}.bi-operations .text-button{margin-top:10px}.operation-message{color:#965c35}@media(max-width:650px){.operation-title{flex-wrap:wrap}.operation-status{margin-left:28px}}</style>
